def convert_a_to_b(T, test_cases):
    results = []
    for case in test_cases:
        N = case[0]
        A = case[1]
        B = case[2]

        if A == B:
            results.append([0])
            continue

        if any(a > b for a, b in zip(A, B)):
            results.append([-1])
            continue

        operations = []
        used = [False] * N
        for i in range(N):
            if A[i] != B[i]:
                min_char = min(A[i], B[i])
                operation = [1, i]
                for j in range(N):
                    if A[j] == min_char and not used[j]:
                        operation.append(j)
                        used[j] = True
                operations.append(operation)

        results.append([len(operations)] + [operation for operation in operations])

    return results

# Read input
T = int(input())
test_cases = []
for _ in range(T):
    N = int(input())
    A = input()
    B = input()
    test_cases.append((N, A, B))

# Get results
results = convert_a_to_b(T, test_cases)

# Print results
for result in results:
